#include <stdio.h>

int main() {
    // do-while loop implementation
    // i starts past the limit, yet the body runs once
    printf("Post-test loop implementation\n");
    int i = 6;
    do {
        printf("%d\n", i);
        i++;
    } while (i <= 5);

    printf("Loop finished\n");

    return 0;
}
